// 2. Validate Input
// Confirms the correlated incident from WF-05 has what the routing
// engine needs to make a team/priority/policy decision.

const REQUIRED = ['incidentId', 'siteId', 'vendor', 'region'];

const item = $input.first().json;
const missing = REQUIRED.filter((f) => item[f] === undefined || item[f] === null || item[f] === '');

if (!item.rootAlarm || !item.rootAlarm.alarmType) {
  missing.push('rootAlarm.alarmType');
}

return [{
  json: {
    isValid: missing.length === 0,
    missingFields: missing,
    ...item
  }
}];

// 3. Determine Team Assignment
// Business rule matrix: maps each alarmType to the team responsible.
// Mirrors WF-03's alarm-type business rules (Fiber Cut -> Transmission,
// LOS -> NOC, High BER -> Transmission Monitoring, Power Failure -> Power,
// Mux Failure -> Transmission), extended to cover every alarmType WF-02
// can produce, and expressed using WF-07's exact team-name conventions so
// every alarm resolves to a real Telegram destination downstream.
// Unmapped/unknown alarm types fall back to NOC rather than being
// unroutable.

const item = $input.first().json;
const alarmType = item.rootAlarm ? item.rootAlarm.alarmType : null;

const ALARM_TYPE_TEAM_MAP = {
  FIBER_CUT: 'Transmission Team',
  OTN_PORT_DOWN: 'Transmission Team',
  DWDM_CARD_FAILURE: 'Transmission Team',
  MUX_FAILURE: 'Transmission Team',
  LOS: 'NOC',
  LOF: 'NOC',
  HIGH_BER: 'Transmission Monitoring',
  HIGH_ATTENUATION: 'Transmission Monitoring',
  POWER_FAILURE: 'Power Team',
  SITE_DOWN: 'Site Maintenance Team',
  TEMPERATURE_ALARM: 'Site Maintenance Team',
  LINK_DOWN: 'IP Network Team',
  OTHER: 'NOC'
};

const DEFAULT_TEAM = 'NOC';
const teamMatched = Object.prototype.hasOwnProperty.call(ALARM_TYPE_TEAM_MAP, alarmType);
const assignedTeam = teamMatched ? ALARM_TYPE_TEAM_MAP[alarmType] : DEFAULT_TEAM;

return [{
  json: {
    ...item,
    assignedTeam,
    teamMatched
  }
}];

// 4. Determine Priority & Notification Policy
// Priority: uses the root alarm's own priority (set by WF-03's AI
// classification + business rules) as the single source of truth, since
// that is the most alarm-specific signal available. Falls back to
// deriving priority from WF-04's businessPriority score only if the root
// alarm priority is missing.
// notificationPolicy: maps priority to how urgently WF-07/WF-08 should
// treat delivery.

const item = $input.first().json;

function priorityFromBusinessPriority(bp) {
  if (!bp) return 'Warning';
  if (bp.indexOf('P1') === 0) return 'Critical';
  if (bp.indexOf('P2') === 0) return 'Major';
  if (bp.indexOf('P3') === 0) return 'Minor';
  return 'Warning';
}

const priority = (item.rootAlarm && item.rootAlarm.priority)
  || priorityFromBusinessPriority(item.businessPriority);

const NOTIFICATION_POLICY_MAP = {
  Critical: 'immediate',
  Major: 'urgent',
  Minor: 'standard',
  Warning: 'digest'
};

const notificationPolicy = NOTIFICATION_POLICY_MAP[priority] || 'standard';

return [{
  json: {
    ...item,
    priority,
    notificationPolicy
  }
}];

// 5. Compute Escalation & SLA
// escalationLevel: L1 (highest) for Critical priority or alarm storms
// (occurrenceCount > 3 correlated child alarms), L2 for Major, L3 for
// Minor/Warning.
// immediateEscalation: true whenever escalationLevel is L1 - drives
// WF-07's "IMMEDIATE ESCALATION" marker.
// slaDeadline: now + a response window sized to priority.

const item = $input.first().json;

const SLA_MINUTES = {
  Critical: 30,
  Major: 120,
  Minor: 480,
  Warning: 1440
};

const occurrenceCount = typeof item.occurrenceCount === 'number' ? item.occurrenceCount : 1;
const isAlarmStorm = occurrenceCount > 3;

let escalationLevel;
if (item.priority === 'Critical' || isAlarmStorm) {
  escalationLevel = 'L1';
} else if (item.priority === 'Major') {
  escalationLevel = 'L2';
} else {
  escalationLevel = 'L3';
}

const immediateEscalation = escalationLevel === 'L1';

const slaMinutes = SLA_MINUTES[item.priority] || SLA_MINUTES.Warning;
const slaDeadline = new Date(Date.now() + slaMinutes * 60 * 1000).toISOString();

return [{
  json: {
    ...item,
    escalationLevel,
    immediateEscalation,
    slaDeadline,
    isAlarmStorm
  }
}];

// 6. Build Routing Decision
// Assembles the final routing decision in the exact shape WF-07's
// '2. Validate Input' requires (incidentId, siteId, assignedTeam,
// priority, notificationPolicy), plus the optional fields WF-07's
// '4. Build Notification Payload' uses when present (correlationId,
// escalationLevel, immediateEscalation, slaDeadline, businessImpact,
// affectedCustomers). This is the payload that closes the WF-05 -> WF-07
// schema gap.

const item = $input.first().json;

const businessImpact = [
  item.businessPriority || null,
  item.impact ? (item.impact + ' customer impact') : null,
  typeof item.affectedCustomers === 'number' ? (item.affectedCustomers + ' customers affected') : null
].filter(Boolean).join(' - ') || 'Business impact not available';

return [{
  json: {
    incidentId: item.incidentId,
    correlationId: (item.rootAlarm && item.rootAlarm.correlationId) || null,
    siteId: item.siteId,
    assignedTeam: item.assignedTeam,
    priority: item.priority,
    notificationPolicy: item.notificationPolicy,
    escalationLevel: item.escalationLevel,
    immediateEscalation: item.immediateEscalation,
    slaDeadline: item.slaDeadline,
    businessImpact,
    affectedCustomers: typeof item.affectedCustomers === 'number' ? item.affectedCustomers : 0,
    vendor: item.vendor,
    region: item.region,
    routedAt: new Date().toISOString(),
    nextWorkflow: 'notification-dispatcher'
  }
}];
